1	use std::f64::consts::TAU;
2	
3	use typst_library::foundations::Repr;
4	use typst_library::layout::{
5	    Abs, Angle, Axes, Frame, Point, Quadrant, Ratio, Size, Transform,
6	};
7	use typst_library::visualize::{
8	    Color, FillRule, Gradient, GradientStop, Paint, ProcessColor, RatioOrAngle, Tiling,
9	};
10	use xmlwriter::XmlWriter;
11	
12	use crate::path::SvgPathBuilder;
13	use crate::write::{SvgDisplay, SvgElem, SvgIdRef, SvgTransform, SvgUrl, SvgWrite};
14	use crate::{DedupId, SVGRenderer, State};
15	
16	/// The number of segments in a conic gradient.
17	/// This is a heuristic value that seems to work well.
18	/// Smaller values could be interesting for optimization.
19	const NUM_CONIC_SEGMENTS: usize = 360;
20	
21	impl SVGRenderer<'_> {
22	    /// Render a frame to a string.
23	    pub(super) fn render_tiling_frame(&mut self, state: &State, frame: &Frame) -> String {
24	        let mut xml = XmlWriter::new(xmlwriter::Options::default());
25	        let mut svg = SvgElem::new(&mut xml, "g");
26	        self.render_frame(&mut svg, state, frame);
27	        drop(svg);
28	        xml.end_document()
29	    }
30	
31	    /// Write a fill attribute.
32	    pub(super) fn write_fill(
33	        &mut self,
34	        svg: &mut SvgElem,
35	        fill: &Paint,
36	        fill_rule: FillRule,
37	        aspect_ratio: Ratio,
38	        ts: Transform,
39	    ) {
40	        match fill {
41	            Paint::Solid(color) => {
42	                svg.attr("fill", color);
43	            }
44	            Paint::Gradient(gradient) => {
45	                let id = self.push_gradient(gradient, aspect_ratio, ts);
46	                svg.attr("fill", SvgUrl(id));
47	            }
48	            Paint::Tiling(tiling) => {
49	                let id = self.push_tiling(tiling, ts);
50	                svg.attr("fill", SvgUrl(id));
51	            }
52	        }
53	        match fill_rule {
54	            FillRule::NonZero => svg.attr("fill-rule", "nonzero"),
55	            FillRule::EvenOdd => svg.attr("fill-rule", "evenodd"),
56	        };
57	    }
58	
59	    /// Pushes a gradient to the list of gradients to write SVG file.
60	    ///
61	    /// If the gradient is already present, returns the id of the existing
62	    /// gradient. Otherwise, inserts the gradient and returns the id of the
63	    /// inserted gradient. If the transform of the gradient is the identify
64	    /// matrix, the returned ID will be the ID of the "source" gradient,
65	    /// this is a file size optimization.
66	    pub(super) fn push_gradient(
67	        &mut self,
68	        gradient: &Gradient,
69	        aspect_ratio: Ratio,
70	        ts: Transform,
71	    ) -> DedupId {
72	        let gradient_id = self
73	            .gradients
74	            .insert_with((gradient, aspect_ratio), || (gradient.clone(), aspect_ratio));
75	
76	        if ts.is_identity() {
77	            return gradient_id;
78	        }
79	
80	        self.gradient_refs.insert_with(&(gradient_id, ts), || GradientRef {
81	            id: gradient_id,
82	            kind: gradient.into(),
83	            transform: ts,
84	        })
85	    }
86	
87	    pub(super) fn push_tiling(&mut self, tiling: &Tiling, ts: Transform) -> DedupId {
88	        let tiling_size = tiling.size() + tiling.spacing();
89	        let tiling_offset = tiling.offset();
90	        let tiling_angle = tiling.angle();
91	        // Unfortunately due to a limitation of `xmlwriter`, we need to
92	        // render the frame twice: once to allocate all of the resources
93	        // that it needs and once to actually render it.
94	        let rendered = self.render_tiling_frame(&State::new(tiling_size), tiling.frame());
95	
96	        // Use the rendered SVG and the tiling's properties as a key, since the
97	        // `Tiling` itself includes `Location`s which aren't stable.
98	        let tiling_id = self.tilings.insert_with(
99	            (tiling_size, tiling_offset, tiling_angle, rendered.as_str()),
100	            || tiling.clone(),
101	        );
102	
103	        if ts.is_identity() {
104	            return tiling_id;
105	        }
106	
107	        // The tiling reference is written as a SVG `pattern` with a `href`
108	        // attribute, which will overwrite the `patternTransform` of the
109	        // referenced pattern. Thus any pre-existing `patternTransform` of the
110	        // referenced pattern needs to be concatenated.
111	        let transform = ts.pre_concat(tiling.transform());
112	        let tiling_ref = TilingRef { id: tiling_id, transform };
113	        self.tiling_refs.insert_with(tiling_ref, || tiling_ref)
114	    }
115	
116	    /// Write the raw gradients (without transform) to the SVG file.
117	    pub(super) fn write_gradients(&mut self, svg: &mut SvgElem) {
118	        if self.gradients.is_empty() {
119	            return;
120	        }
121	
122	        let mut defs = svg.elem("defs");
123	        for (id, (gradient, aspect_ratio)) in self.gradients.iter() {
124	            let mut svg = match &gradient {
125	                Gradient::Linear(linear) => {
126	                    let mut gradient = defs.elem("linearGradient");
127	                    gradient.attr("id", id);
128	                    gradient.attr("spreadMethod", "pad");
129	                    gradient.attr("gradientUnits", "userSpaceOnUse");
130	
131	                    let angle =
132	                        Gradient::correct_aspect_ratio(linear.angle, *aspect_ratio);
133	                    let (sin, cos) = (angle.sin(), angle.cos());
134	
135	                    // Scale to edges of unit square.
136	                    let factor = sin.abs() + cos.abs();
137	
138	                    let (x1, y1) = match angle.quadrant() {
139	                        Quadrant::First => (0.0, 0.0),
140	                        Quadrant::Second => (1.0, 0.0),
141	                        Quadrant::Third => (1.0, 1.0),
142	                        Quadrant::Fourth => (0.0, 1.0),
143	                    };
144	                    let x2 = x1 + (cos * factor);
145	                    let y2 = y1 + (sin * factor);
146	
147	                    gradient.attr("x1", x1);
148	                    gradient.attr("y1", y1);
149	                    gradient.attr("x2", x2);
150	                    gradient.attr("y2", y2);
151	
152	                    gradient
153	                }
154	                Gradient::Radial(radial) => {
155	                    let mut gradient = defs.elem("radialGradient");
156	                    gradient.attr("id", id);
157	                    gradient.attr("spreadMethod", "pad");
158	                    gradient.attr("gradientUnits", "userSpaceOnUse");
159	                    gradient.attr("cx", radial.center.x.get());
160	                    gradient.attr("cy", radial.center.y.get());
161	                    gradient.attr("r", radial.radius.get());
162	                    gradient.attr("fx", radial.focal_center.x.get());
163	                    gradient.attr("fy", radial.focal_center.y.get());
164	                    gradient.attr("fr", radial.focal_radius.get());
165	                    gradient
166	                }
167	                Gradient::Conic(conic) => {
168	                    let mut pattern = defs.elem("pattern");
169	                    pattern.attr("id", id);
170	                    pattern.attr("viewBox", "0 0 1 1");
171	                    pattern.attr("preserveAspectRatio", "none");
172	                    pattern.attr("patternUnits", "userSpaceOnUse");
173	                    pattern.attr("width", "2");
174	                    pattern.attr("height", "2");
175	                    // TODO: Refactor this.
176	                    pattern.attr("x", "-0.5");
177	                    pattern.attr("y", "-0.5");
178	
179	                    let center = conic.center;
180	
181	                    // Correct the angles with the inverse aspect-ratio, to
182	                    // compensate for the transformation that is applied later
183	                    // on to the gradient fill.
184	                    let inverse_ratio = aspect_ratio.recip();
185	
186	                    // We build an arg segment for each segment of a circle.
187	                    let dtheta = Angle::rad(TAU / NUM_CONIC_SEGMENTS as f64);
188	                    for i in 0..NUM_CONIC_SEGMENTS {
189	                        // Negate the angle for clockwise gradient rotation.
190	                        let theta1 = -Gradient::correct_aspect_ratio(
191	                            conic.angle + (dtheta * i as f64),
192	                            inverse_ratio,
193	                        );
194	                        let theta2 = -Gradient::correct_aspect_ratio(
195	                            conic.angle + (dtheta * (i + 1) as f64),
196	                            inverse_ratio,
197	                        );
198	
199	                        // Create the path for the segment.
200	                        let mut builder = SvgPathBuilder::empty();
201	                        builder.move_to(correct_tiling_pos(center.x, center.y));
202	
203	                        builder.line_to(correct_tiling_pos(
204	                            Ratio::new(-2.0 * theta1.cos()) + center.x,
205	                            Ratio::new(2.0 * theta1.sin()) + center.y,
206	                        ));
207	                        builder.arc(
208	                            Size::splat(Abs::pt(1.0)),
209	                            Angle::zero(),
210	                            0,
211	                            1,
212	                            correct_tiling_pos(
213	                                Ratio::new(-2.0 * theta2.cos()) + center.x,
214	                                Ratio::new(2.0 * theta2.sin()) + center.y,
215	                            ),
216	                        );
217	                        builder.close();
218	
219	                        let t1 = (i as f64) / NUM_CONIC_SEGMENTS as f64;
220	                        let t2 = (i + 1) as f64 / NUM_CONIC_SEGMENTS as f64;
221	                        let subgradient = SVGSubGradient {
222	                            center: conic.center,
223	                            t0: theta1,
224	                            t1: theta2,
225	                            c0: gradient.sample(RatioOrAngle::Ratio(Ratio::new(t1))),
226	                            c1: gradient.sample(RatioOrAngle::Ratio(Ratio::new(t2))),
227	                        };
228	                        let id = self
229	                            .conic_subgradients
230	                            .insert_with(subgradient.clone(), || subgradient);
231	
232	                        // Add the path to the pattern.
233	                        pattern
234	                            .elem("path")
235	                            .attr("d", builder.finsish())
236	                            .attr("fill", SvgUrl(id))
237	                            .attr("stroke", "none")
238	                            .attr("shape-rendering", "optimizeSpeed");
239	                    }
240	
241	                    // We skip the default stop generation code.
242	                    continue;
243	                }
244	            };
245	
246	            // Unwraps of to_space with this and the stops are safe since the
247	            // stops have been checked before to be compatible with the
248	            // gradient.
249	            let gradient_space = gradient.space();
250	
251	            for window in gradient.stops_ref().windows(2) {
252	                let (start_c, start_t) = &window[0];
253	                let (end_c, end_t) = &window[1];
254	
255	                svg.elem("stop").attr("offset", start_t.repr()).attr(
256	                    "stop-color",
257	                    start_c.to_space(&gradient_space).unwrap().to_hex(),
258	                );
259	
260	                // Generate intermediate stops between the two stops.
261	                // This is a workaround for a bug in many readers:
262	                // They tend to just ignore the color space of the gradient.
263	                if end_t > start_t && gradient.anti_alias() {
264	                    let start = GradientStop::new(start_c.clone(), *start_t);
265	                    let end = GradientStop::new(end_c.clone(), *end_t);
266	                    gradient
267	                        .generate_intermediate_stops_for_rgb_interpolation(&start, &end)
268	                        .for_each(|(c, t)| {
269	                            let c = c.to_space(&gradient.space()).unwrap();
270	                            svg.elem("stop")
271	                                .attr("offset", t.repr())
272	                                .attr("stop-color", c.to_hex());
273	                        });
274	                }
275	            }
276	
277	            if let Some((last_c, last_t)) = gradient.stops_ref().last() {
278	                svg.elem("stop").attr("offset", last_t.repr()).attr(
279	                    "stop-color",
280	                    last_c.to_space(&gradient.space()).unwrap().to_hex(),
281	                );
282	            }
283	        }
284	    }
285	
286	    /// Write the sub-gradients that are used for conic gradients.
287	    pub(super) fn write_subgradients(&mut self, svg: &mut SvgElem) {
288	        if self.conic_subgradients.is_empty() {
289	            return;
290	        }
291	
292	        let mut defs = svg.elem("defs");
293	        for (id, gradient) in self.conic_subgradients.iter() {
294	            let x1 = 2.0 - gradient.t0.cos() + gradient.center.x.get();
295	            let y1 = gradient.t0.sin() + gradient.center.y.get();
296	            let x2 = 2.0 - gradient.t1.cos() + gradient.center.x.get();
297	            let y2 = gradient.t1.sin() + gradient.center.y.get();
298	
299	            defs.elem("linearGradient")
300	                .attr("id", id)
301	                .attr("gradientUnits", "objectBoundingBox")
302	                .attr("x1", x1)
303	                .attr("y1", y1)
304	                .attr("x2", x2)
305	                .attr("y2", y2)
306	                .with(|svg| {
307	                    svg.elem("stop")
308	                        .attr("offset", "0%")
309	                        .attr("stop-color", gradient.c0.to_hex());
310	
311	                    svg.elem("stop")
312	                        .attr("offset", "100%")
313	                        .attr("stop-color", gradient.c1.to_hex());
314	                });
315	        }
316	    }
317	
318	    pub(super) fn write_gradient_refs(&mut self, svg: &mut SvgElem) {
319	        if self.gradient_refs.is_empty() {
320	            return;
321	        }
322	
323	        let mut defs = svg.elem("defs");
324	        for (id, gradient_ref) in self.gradient_refs.iter() {
325	            let (elem_name, transform_name) = match gradient_ref.kind {
326	                GradientKind::Linear => ("linearGradient", "gradientTransform"),
327	                GradientKind::Radial => ("radialGradient", "gradientTransform"),
328	                GradientKind::Conic => ("pattern", "patternTransform"),
329	            };
330	            defs.elem(elem_name)
331	                .attr(transform_name, SvgTransform(gradient_ref.transform))
332	                .attr("id", id)
333	                // Writing the href attribute to the "reference" gradient.
334	                .attr("href", SvgIdRef(gradient_ref.id))
335	                // Also writing the xlink:href attribute for compatibility.
336	                .attr("xlink:href", SvgIdRef(gradient_ref.id));
337	        }
338	    }
339	
340	    /// Write the raw tilings (without transform) to the SVG file.
341	    pub(super) fn write_tilings(&mut self, svg: &mut SvgElem) {
342	        if self.tilings.is_empty() {
343	            return;
344	        }
345	
346	        let mut defs = svg.elem("defs");
347	        for (id, tiling) in
348	            self.tilings.iter().map(|(i, p)| (i, p.clone())).collect::<Vec<_>>()
349	        {
350	            let size = tiling.size() + tiling.spacing();
351	
352	            defs.elem("pattern")
353	                .attr("id", id)
354	                .attr("width", size.x.to_pt())
355	                .attr("height", size.y.to_pt())
356	                .attr("patternUnits", "userSpaceOnUse")
357	                .attr("patternTransform", SvgTransform(tiling.transform()))
358	                .attr_with("viewBox", |attr| {
359	                    attr.push_nums([0.0, 0.0, size.x.to_pt(), size.y.to_pt()]);
360	                })
361	                .with(|pattern| {
362	                    // Render the frame.
363	                    let state = State::new(size);
364	                    self.render_frame(pattern, &state, tiling.frame());
365	                });
366	        }
367	    }
368	
369	    /// Writes the references to the deduplicated tilings for each usage site.
370	    pub(super) fn write_tiling_refs(&mut self, svg: &mut SvgElem) {
371	        if self.tiling_refs.is_empty() {
372	            return;
373	        }
374	
375	        let mut defs = svg.elem("defs");
376	        for (id, tiling_ref) in self.tiling_refs.iter() {
377	            defs.elem("pattern")
378	                .attr("patternTransform", SvgTransform(tiling_ref.transform))
379	                .attr("id", id)
380	                // Writing the href attribute to the "reference" pattern.
381	                .attr("href", SvgIdRef(tiling_ref.id))
382	                // Also writing the xlink:href attribute for compatibility.
383	                .attr("xlink:href", SvgIdRef(tiling_ref.id));
384	        }
385	    }
386	}
387	
388	/// A reference to a deduplicated tiling, with a transform matrix.
389	///
390	/// Allows tilings to be reused across multiple invocations, simply by changing
391	/// the transform matrix.
392	#[derive(Copy, Clone, Hash)]
393	pub struct TilingRef {
394	    /// The ID of the deduplicated gradient
395	    id: DedupId,
396	    /// The transform matrix to apply to the tiling.
397	    transform: Transform,
398	}
399	
400	/// A reference to a deduplicated gradient, with a transform matrix.
401	///
402	/// Allows gradients to be reused across multiple invocations,
403	/// simply by changing the transform matrix.
404	#[derive(Hash)]
405	pub struct GradientRef {
406	    /// The ID of the deduplicated gradient
407	    id: DedupId,
408	    /// The gradient kind (used to determine the SVG element to use)
409	    /// but without needing to clone the entire gradient.
410	    kind: GradientKind,
411	    /// The transform matrix to apply to the gradient.
412	    transform: Transform,
413	}
414	
415	/// A subgradient for conic gradients.
416	#[derive(Clone, Hash)]
417	pub struct SVGSubGradient {
418	    /// The center point of the gradient.
419	    center: Axes<Ratio>,
420	    /// The start point of the subgradient.
421	    t0: Angle,
422	    /// The end point of the subgradient.
423	    t1: Angle,
424	    /// The color at the start point of the subgradient.
425	    c0: Color,
426	    /// The color at the end point of the subgradient.
427	    c1: Color,
428	}
429	
430	/// The kind of linear gradient.
431	#[derive(Copy, Clone, Eq, PartialEq, Hash)]
432	enum GradientKind {
433	    /// A linear gradient.
434	    Linear,
435	    /// A radial gradient.
436	    Radial,
437	    /// A conic gradient.
438	    Conic,
439	}
440	
441	impl From<&Gradient> for GradientKind {
442	    fn from(value: &Gradient) -> Self {
443	        match value {
444	            Gradient::Linear { .. } => GradientKind::Linear,
445	            Gradient::Radial { .. } => GradientKind::Radial,
446	            Gradient::Conic { .. } => GradientKind::Conic,
447	        }
448	    }
449	}
450	
451	impl SvgDisplay for Color {
452	    fn fmt(&self, f: &mut impl SvgWrite) {
453	        match self.to_process() {
454	            c @ (ProcessColor::Rgb(_)
455	            | ProcessColor::Luma(_)
456	            | ProcessColor::Cmyk(_)
457	            | ProcessColor::Hsv(_)) => {
458	                f.push_str(&c.to_hex());
459	            }
460	            ProcessColor::LinearRgb(rgb) => {
461	                f.push_str("color(srgb-linear ");
462	                f.push_nums([rgb.red, rgb.green, rgb.blue].map(round::<5>));
463	                if rgb.alpha != 1.0 {
464	                    f.push_str(" / ");
465	                    f.push_num(round::<5>(rgb.alpha));
466	                }
467	                f.push_str(")");
468	            }
469	            ProcessColor::Oklab(oklab) => {
470	                f.push_str("oklab(");
471	                f.push_num(round::<3>(100.0 * oklab.l));
472	                f.push_str("% ");
473	                f.push_nums([oklab.a, oklab.b].map(round::<5>));
474	                if oklab.alpha != 1.0 {
475	                    f.push_str(" / ");
476	                    f.push_num(round::<5>(oklab.alpha));
477	                }
478	                f.push_str(")");
479	            }
480	            ProcessColor::Oklch(oklch) => {
481	                f.push_str("oklch(");
482	                f.push_num(round::<3>(100.0 * oklch.l));
483	                f.push_str("% ");
484	                f.push_num(round::<5>(oklch.chroma));
485	                f.push_str(" ");
486	                f.push_num(round::<5>(oklch.hue.into_degrees()));
487	                if oklch.alpha != 1.0 {
488	                    f.push_str(" / ");
489	                    f.push_num(round::<5>(oklch.alpha));
490	                }
491	                f.push_str(")");
492	            }
493	            ProcessColor::Hsl(hsl) => {
494	                if hsl.alpha != 1.0 {
495	                    f.push_str("hsla(");
496	                } else {
497	                    f.push_str("hsl(");
498	                }
499	                f.push(round::<3>(hsl.hue.into_degrees()));
500	                f.push_str("deg ");
501	                f.push(round::<3>(100.0 * hsl.saturation));
502	                f.push_str("% ");
503	                f.push(round::<3>(100.0 * hsl.lightness));
504	                if hsl.alpha != 1.0 {
505	                    f.push_str(" / ");
506	                    f.push_num(round::<5>(hsl.alpha));
507	                }
508	                f.push_str(")");
509	            }
510	        }
511	    }
512	}
513	
514	fn round<const DIGITS: u32>(num: f32) -> f64 {
515	    let factor = 10_u32.pow(DIGITS) as f64;
516	    (num as f64 * factor).round() / factor
517	}
518	
519	/// Maps a coordinate in a unit size square to a coordinate in the tiling.
520	pub fn correct_tiling_pos(x: Ratio, y: Ratio) -> Point {
521	    0.5 * Point::new(Abs::pt(x.get() + 0.5), Abs::pt(y.get() + 0.5))
522	}
