141	                svg.attr("stroke", SvgUrl(id));
142	            }
143	            Paint::Tiling(tiling) => {
144	                let id = self.push_tiling(tiling, fill_transform);
145	                svg.attr("stroke", SvgUrl(id));
146	            }
147	        }
148	
149	        svg.attr("stroke-width", stroke.thickness.to_pt());
150	        svg.attr(
151	            "stroke-linecap",
152	            match stroke.cap {
153	                LineCap::Butt => "butt",
154	                LineCap::Round => "round",
155	                LineCap::Square => "square",
156	            },
157	        );
158	        svg.attr(
159	            "stroke-linejoin",
160	            match stroke.join {
161	                LineJoin::Miter => "miter",
162	                LineJoin::Round => "round",
163	                LineJoin::Bevel => "bevel",
164	            },
165	        );
166	        svg.attr("stroke-miterlimit", stroke.miter_limit.get());
167	        if let Some(dash) = &stroke.dash {
168	            svg.attr("stroke-dashoffset", dash.phase.to_pt());
169	            svg.attr_with("stroke-dasharray", |attr| {
170	                attr.push_nums(dash.array.iter().map(|dash| dash.to_pt()));
171	            });
172	        }
173	    }
174	}
