176	/// Convert a geometry to an SVG path.
177	#[comemo::memoize]
178	fn convert_geometry_to_path(geometry: &Geometry) -> EcoString {
179	    let mut builder = SvgPathBuilder::with_translate(Point::zero());
180	    match geometry {
181	        &Geometry::Line(t) => builder.line_to(t),
182	        &Geometry::Rect(size) => builder.rect(size),
183	        Geometry::Curve(p) => {
