191	    let mut builder = SvgPathBuilder::with_translate(initial_point);
192	    for item in &curve.0 {
193	        match *item {
194	            CurveItem::Move(pos) => builder.move_to(pos),
195	            CurveItem::Line(pos) => builder.line_to(pos),
196	            CurveItem::Cubic(p1, p2, p3) => builder.curve_to(p1, p2, p3),
197	            CurveItem::Close => builder.close(),
198	        }
199	    }
200	    builder.finsish()
