162	fn xml_options(pretty: bool) -> xmlwriter::Options {
163	    xmlwriter::Options {
164	        use_single_quote: false,
165	        indent: if pretty {
166	            xmlwriter::Indent::Spaces(2)
167	        } else {
168	            xmlwriter::Indent::None
169	        },
170	        attributes_indent: xmlwriter::Indent::None,
171	    }
172	}
